using System.Text.Json;
using System.Text.RegularExpressions;
using Htt.Infrastructure;
using Htt.SharedKernel;
using Htt.Infrastructure.Documents;
using System.Security.Cryptography;
using NpgsqlTypes;
using static Htt.Host.Api.MasterData.MasterDataSupport;
using static Htt.Host.Api.Sales.SalesSupport;
namespace Htt.Host.Api.MasterData;
public sealed record CrmDraftData(string Name,string? Code=null,string? Abn=null,string? Email=null,string? Phone=null,string? Mobile=null,string? JobTitle=null,string? AddressLine1=null,string? Suburb=null,string? State=null,string? Postcode=null,Guid[]? BranchIds=null);
public sealed record CrmDraftInput(Guid Id,string Kind,Guid? CustomerId,CrmDraftData Data);
public sealed record CrmReview(bool Approve,string Reason);
public sealed record MobileDevice(Guid DeviceId);
public sealed record MobileOperation(Guid OperationId,long Sequence,Guid Id,string Action,long? Version=null,string? Kind=null,Guid? CustomerId=null,CrmDraftData? Data=null);
public sealed record ContactImport(Guid CustomerId,string ConsentReference,IReadOnlyList<CrmDraftData> SelectedContacts);
public sealed record ContactImportConfirmation(int[] Rows);
internal static class CrmDraftEndpoints
{
 private static async Task<object> JsonValue(CompanySession s,string sql,CancellationToken ct,params DbArg[] args)=>Element((await One(s,sql+"::text AS body",ct,args))["body"]!);
 private static Task<List<Dictionary<string,object?>>> Guard(CompanySession s,Guid id,string action,CancellationToken ct)=>Read(s,"SELECT crm.require_mobile_draft(@id,@action)",ct,new DbArg("id",id),new DbArg("action",action));
 internal static CrmDraftData Normalize(string kind,CrmDraftData d)
 {
  Check.That(d is not null,"data","Draft details required.");d=d! with{Name=Check.Text(d!.Name,"name"),Code=kind is "CUSTOMER" or "BRANCH"?Check.Code(d.Code):null,Abn=kind=="CUSTOMER"&&!string.IsNullOrWhiteSpace(d.Abn)?AustralianBusinessNumber.Normalize(d.Abn):null,Email=kind=="CONTACT"?Check.Email(d.Email)?.ToLowerInvariant():null,Phone=kind=="CONTACT"?Phone(d.Phone):null,Mobile=kind=="CONTACT"?Phone(d.Mobile):null,JobTitle=kind=="CONTACT"?Check.Optional(d.JobTitle,"jobTitle",100):null,BranchIds=kind=="CONTACT"?Check.BranchIds(d.BranchIds):[],AddressLine1=kind=="BRANCH"?Check.Text(d.AddressLine1,"addressLine1",300):null,Suburb=kind=="BRANCH"?Check.Optional(d.Suburb,"suburb"):null,State=kind=="BRANCH"?Check.Text(d.State,"state",3).ToUpperInvariant():null,Postcode=kind=="BRANCH"?Check.Text(d.Postcode,"postcode",4):null};if(kind=="BRANCH")Check.Address("AU",d.State,d.Postcode);return d;
 }
 private static string? Phone(string? x){x=Check.Phone(x,"phone");if(x is null)return null;var compact=Regex.Replace(x,"[(). -]","");if(compact.Length==10&&compact[0]=='0'&&compact.All(char.IsAsciiDigit))compact="+61"+compact[1..];return compact;}
 private static CrmDraftInput Normalize(CrmDraftInput x)
 {Check.That(x.Id!=Guid.Empty,"id","Stable client draft ID required.");Check.OneOf(x.Kind,"kind","CUSTOMER","BRANCH","CONTACT");Check.That((x.Kind=="CUSTOMER")== (x.CustomerId is null)&&x.CustomerId!=Guid.Empty,"customerId","Link branch/contact to an existing accessible customer.");return x with{Data=Normalize(x.Kind,x.Data)};}
 public static void Map(RouteGroupBuilder g)
 {
  g.MapGet("/crm/drafts",async(string? state,int? page,int? pageSize,CompanySession s,CancellationToken ct)=>{if(state is not null)Check.OneOf(state,"state","DRAFT","SUBMITTED","APPROVED","REJECTED","DELETED");var(offset,size)=Page(page,pageSize);return Results.Ok(new{items=(await Read(s,"SELECT crm.draft_json(id)::text AS body FROM crm.mobile_drafts WHERE company_id=@company AND(owner_id=@actor OR crm.mobile_reviewer())AND crm.mobile_customer_visible(customer_id)AND(@state IS NULL OR state=@state)ORDER BY updated_at DESC,id LIMIT @size OFFSET @offset",ct,new DbArg("state",state,NpgsqlDbType.Text),new DbArg("size",size),new DbArg("offset",offset))).Select(r=>Element(r["body"]!)),page=page??1,pageSize=size});}).WithMetadata(new Permission("crm.drafts.read"));
  g.MapGet("/crm/drafts/{id:guid}",async(Guid id,CompanySession s,CancellationToken ct)=>{await Guard(s,id,"READ",ct);return Results.Ok(await JsonValue(s,"SELECT crm.draft_json(@id)",ct,new DbArg("id",id)));}).WithMetadata(new Permission("crm.drafts.read"));
  g.MapGet("/crm/drafts/{id:guid}/duplicates",async(Guid id,CompanySession s,CancellationToken ct)=>{await Guard(s,id,"READ",ct);return Results.Ok(await JsonValue(s,"SELECT (SELECT crm.mobile_duplicates(kind,customer_id,data)FROM crm.mobile_drafts WHERE company_id=@company AND id=@id)",ct,new DbArg("id",id)));}).WithMetadata(new Permission("crm.drafts.read"));
  g.MapPost("/crm/drafts",Create).WithMetadata(new Permission("crm.drafts.write"));
  g.MapPut("/crm/drafts/{id:guid}",Update).WithMetadata(new Permission("crm.drafts.write"));
  g.MapPost("/crm/drafts/{id:guid}/submit",async(Guid id,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>await Change(id,"SUBMIT",null,h,s,idem,ct)).WithMetadata(new Permission("crm.drafts.write"));
  g.MapDelete("/crm/drafts/{id:guid}",async(Guid id,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>await Change(id,"DELETE",null,h,s,idem,ct)).WithMetadata(new Permission("crm.drafts.write"));
  g.MapPost("/crm/drafts/{id:guid}/review",Review).WithMetadata(new Permission("crm.drafts.review"));
  g.MapPost("/crm/mobile/devices",async(MobileDevice x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{Check.That(x.DeviceId!=Guid.Empty,"deviceId","Device ID required.");if((await Read(s,"SELECT id FROM crm.mobile_devices WHERE company_id=@company AND id=@id",ct,new DbArg("id",x.DeviceId))).Count>0)await Read(s,"SELECT crm.require_mobile_device(@id)",ct,new DbArg("id",x.DeviceId));return await Write("device",x,h,s,idem,ct,()=>JsonValue(s,"SELECT crm.register_mobile_device(@id)",ct,new DbArg("id",x.DeviceId)),201);}).WithMetadata(new Permission("crm.mobile.sync"));
  g.MapDelete("/crm/mobile/devices/{device:guid}",async(Guid device,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{await Read(s,"SELECT crm.require_mobile('crm.drafts.read')",ct);await One(s,"SELECT id FROM crm.mobile_devices WHERE company_id=@company AND id=@device AND actor_id=@actor",ct,new DbArg("device",device));return await Write("device_revoke",new{device},h,s,idem,ct,async()=>{await Read(s,"SELECT crm.revoke_mobile_device(@device)",ct,new DbArg("device",device));return new{deviceId=device,active=false};});}).WithMetadata(new Permission("crm.mobile.sync"));
  g.MapPost("/crm/mobile/devices/{device:guid}/operations",Push).WithMetadata(new Permission("crm.mobile.sync"));
  g.MapGet("/crm/mobile/devices/{device:guid}/changes",async(Guid device,long? after,string? auth,int? pageSize,CompanySession s,CancellationToken ct)=>Results.Ok(await JsonValue(s,"SELECT crm.mobile_pull(@device,@after,@auth,@size)",ct,new DbArg("device",device),new DbArg("after",after??0),new DbArg("auth",auth,NpgsqlDbType.Text),new DbArg("size",pageSize??100)))).WithMetadata(new Permission("crm.mobile.sync"));
  g.MapPost("/crm/cards/{customer:guid}",UploadCard).DisableAntiforgery().WithMetadata(new Permission("crm.contacts.import"));
  g.MapGet("/crm/cards/jobs/{id:guid}",async(Guid id,CompanySession s,CancellationToken ct)=>Results.Ok(await JsonValue(s,"SELECT crm.card_view(@id)",ct,new DbArg("id",id)))).WithMetadata(new Permission("crm.contacts.import"));
  g.MapPost("/crm/cards/jobs/{id:guid}/retry",async(Guid id,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{await Read(s,"SELECT crm.require_card(@id)",ct,new DbArg("id",id));return await Write("card_retry",new{id},h,s,idem,ct,async()=>{await Read(s,"SELECT crm.retry_card(@id)",ct,new DbArg("id",id));return await JsonValue(s,"SELECT crm.card_view(@id)",ct,new DbArg("id",id));});}).WithMetadata(new Permission("crm.contacts.import"));
  g.MapPost("/crm/cards/jobs/{id:guid}/confirm",async(Guid id,CrmDraftData input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)=>{await Read(s,"SELECT crm.require_card(@id)",ct,new DbArg("id",id));var data=Normalize("CONTACT",input);return await Write("card_confirm",new{id,data},h,s,idem,ct,()=>JsonValue(s,"SELECT crm.confirm_card(@id,@data)",ct,new DbArg("id",id),new DbArg("data",Json(data),NpgsqlDbType.Jsonb)),201);}).WithMetadata(new Permission("crm.contacts.import"));
  g.MapPost("/crm/contact-imports",Import).WithMetadata(new Permission("crm.contacts.import"));
  g.MapPost("/crm/contact-imports/{id:guid}/confirm",ConfirmImport).WithMetadata(new Permission("crm.contacts.import"));
 }
 private static async Task<IResult> UploadCard(Guid customer,IFormFile file,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {await Read(s,"SELECT crm.require_mobile('crm.drafts.write'),crm.require_mobile('crm.drafts.read')",ct);await Customer(h,s,customer,ct);Check.That(file.Length is>0 and<=FileRules.MaxBytes,"file","Upload a selected card PNG/JPEG up to 10 MiB.");Check.That(file.ContentType is "image/png" or "image/jpeg","file","Card image required.");await using var input=file.OpenReadStream();using var buffer=new MemoryStream();var block=new byte[8192];int n;while((n=await input.ReadAsync(block,ct))>0){Check.That(buffer.Length+n<=FileRules.MaxBytes,"file","Card image too large.");await buffer.WriteAsync(block.AsMemory(0,n),ct);}var bytes=buffer.ToArray();FileRules.Validate(bytes,file.ContentType,FileRules.Filename(file.FileName));var sha=Convert.ToHexString(SHA256.HashData(bytes));return await Write("card_queue",new{customer,sha,type=file.ContentType},h,s,idem,ct,async()=>{var id=(Guid)(await One(s,"SELECT crm.queue_card(@customer,@type,@bytes)AS id",ct,new DbArg("customer",customer),new DbArg("type",file.ContentType),new DbArg("bytes",bytes,NpgsqlDbType.Bytea)))["id"]!;return await JsonValue(s,"SELECT crm.card_view(@id)",ct,new DbArg("id",id));},202);}
 private static async Task<IResult> Create(CrmDraftInput input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {var x=Normalize(input);await Read(s,"SELECT crm.require_mobile('crm.drafts.read'),crm.require_mobile('crm.drafts.write')",ct);if(x.CustomerId is{}customer)await Customer(h,s,customer,ct);return await Write("create",x,h,s,idem,ct,()=>JsonValue(s,"SELECT crm.create_mobile_draft(@id,@kind,@customer,@data)",ct,new DbArg("id",x.Id),new DbArg("kind",x.Kind),new DbArg("customer",x.CustomerId,NpgsqlDbType.Uuid),new DbArg("data",Json(x.Data),NpgsqlDbType.Jsonb)),201);}
 private static async Task<IResult> Update(Guid id,CrmDraftData input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {await Guard(s,id,"WRITE",ct);var kind=(string)(await One(s,"SELECT kind FROM crm.mobile_drafts WHERE company_id=@company AND id=@id",ct,new DbArg("id",id)))["kind"]!;return await Change(id,"UPDATE",Normalize(kind,input),h,s,idem,ct);}
 private static async Task<IResult> Change(Guid id,string action,CrmDraftData? data,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {await Guard(s,id,"WRITE",ct);var version=Version(h);return await Write(action,new{id,version,data},h,s,idem,ct,()=>JsonValue(s,"SELECT crm.change_mobile_draft(@id,@v,@action,@data)",ct,new DbArg("id",id),new DbArg("v",version),new DbArg("action",action),new DbArg("data",data is null?null:Json(data),NpgsqlDbType.Jsonb)));}
 private static async Task<IResult> Review(Guid id,CrmReview input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {await Guard(s,id,"REVIEW",ct);var version=Version(h);var reason=Check.Text(input.Reason,"reason",2000);return await Write("review",new{id,version,input.Approve,reason},h,s,idem,ct,()=>JsonValue(s,"SELECT crm.review_mobile_draft(@id,@v,@approve,@reason)",ct,new DbArg("id",id),new DbArg("v",version),new DbArg("approve",input.Approve),new DbArg("reason",reason)));}
 private static async Task<IResult> Push(Guid device,MobileOperation input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {await Read(s,"SELECT crm.require_mobile_device(@device),crm.require_mobile('crm.drafts.write')",ct,new DbArg("device",device));Check.That(input.OperationId!=Guid.Empty&&input.Id!=Guid.Empty&&input.Sequence>0,"operation","Stable nonempty operation/draft IDs and increasing device sequence required.");Check.OneOf(input.Action,"action","CREATE","UPDATE","SUBMIT","DELETE");CrmDraftData? data=null;var kind=input.Kind;if(input.Action=="CREATE"){var draft=Normalize(new CrmDraftInput(input.Id,kind!,input.CustomerId,input.Data!));data=draft.Data;if(draft.CustomerId is{}customer)await Customer(h,s,customer,ct);}else{await Guard(s,input.Id,"WRITE",ct);Check.That(input.Version>0,"version","Expected draft version required.");if(input.Action=="UPDATE"){kind=(string)(await One(s,"SELECT kind FROM crm.mobile_drafts WHERE company_id=@company AND id=@id",ct,new DbArg("id",input.Id)))["kind"]!;data=Normalize(kind,input.Data!);}}var request=new{id=input.Id,action=input.Action,version=input.Version,kind,customerId=input.CustomerId,data};return await Write("push",new{device,input.OperationId,input.Sequence,request},h,s,idem,ct,()=>JsonValue(s,"SELECT crm.mobile_push(@device,@operation,@seq,@request)",ct,new DbArg("device",device),new DbArg("operation",input.OperationId),new DbArg("seq",input.Sequence),new DbArg("request",Json(request),NpgsqlDbType.Jsonb)));}
 private static async Task<IResult> Import(ContactImport x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {await Read(s,"SELECT crm.require_mobile('crm.drafts.write'),crm.require_mobile('crm.drafts.read')",ct);await Customer(h,s,x.CustomerId,ct);var consent=Check.Text(x.ConsentReference,"consentReference");Check.That(x.SelectedContacts is{Count:>=1 and<=100},"selectedContacts","Upload only 1..100 user-selected contacts.");var rows=x.SelectedContacts.Select(d=>Normalize("CONTACT",d)).ToArray();return await Write("import-preview",new{x.CustomerId,consent,rows},h,s,idem,ct,()=>JsonValue(s,"SELECT crm.preview_contact_import(@id,@customer,@consent,@rows)",ct,new DbArg("id",Guid.NewGuid()),new DbArg("customer",x.CustomerId),new DbArg("consent",consent),new DbArg("rows",Json(rows),NpgsqlDbType.Jsonb)),201);}
 private static async Task<IResult> ConfirmImport(Guid id,ContactImportConfirmation x,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct)
 {await Read(s,"SELECT crm.require_contact_import(@id)",ct,new DbArg("id",id));Check.That(x.Rows is{Length:>=1 and<=100}&&x.Rows.All(v=>v>=0)&&x.Rows.Distinct().Count()==x.Rows.Length,"rows","Select distinct preview row indexes.");var rows=x.Rows.Order().ToArray();return await Write("import-confirm",new{id,rows},h,s,idem,ct,()=>JsonValue(s,"SELECT crm.confirm_contact_import(@id,@rows)",ct,new DbArg("id",id),new DbArg("rows",rows,NpgsqlDbType.Array|NpgsqlDbType.Integer)),201);}
 private static async Task<IResult> Write(string action,object input,HttpContext h,CompanySession s,Idempotency idem,CancellationToken ct,Func<Task<object>> run,int status=200)
 {var r=await idem.ExecuteAsync("POST /crm/"+action,h.Request.Headers["Idempotency-Key"].ToString(),Json(input),async()=>{var result=await run();var emitted=JsonSerializer.SerializeToElement(result,ApiJson.Options);Guid entity=Guid.Empty;if(emitted.TryGetProperty("id",out var eid)||emitted.TryGetProperty("deviceId",out eid))eid.TryGetGuid(out entity);else if(emitted.TryGetProperty("draft",out var draft)&&draft.TryGetProperty("id",out eid))eid.TryGetGuid(out entity);await Sql.AuditAsync(s,"crm."+action.Replace('-','_'),"crm_draft",entity,h.TraceIdentifier,ct);return ApiJson.Stored(result,status);},ct);return ApiJson.Result(r);}
}
